using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluations;

[TestClass]
public sealed class QualityEvaluationTests
{
    private static ReportingConfiguration? s_reportingConfig;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        var dir = Path.Combine(context.TestRunResultsDirectory!, "eval-results");

        s_reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootDir: dir,
            evaluators:
            [
                new RelevancyEvaluator(),
                new CoherenceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [TestMethod]
    public async Task CoachingRelevance_ShouldScoreAboveThreshold()
    {
        await using var scenario =
            await s_reportingConfig!.CreateScenarioRunAsync(scenarioName: nameof(CoachingRelevance_ShouldScoreAboveThreshold));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to improve my time management skills."),
        };

        var response = await GetCoachResponseAsync(messages);

        var context = "The user is a software developer struggling with task prioritization.";

        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext: [new EvaluationContext("context", context)]);

        var relevance = scenario.GetNumericMetric(RelevancyEvaluator.RelevancyMetricName);
        Assert.IsTrue(relevance.Value >= 3, $"Relevance score {relevance.Value} is below threshold.");
    }

    [TestMethod]
    public async Task CoachingCompleteness_ShouldScoreAboveThreshold()
    {
        await using var scenario =
            await s_reportingConfig!.CreateScenarioRunAsync(scenarioName: nameof(CoachingCompleteness_ShouldScoreAboveThreshold));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How should I prepare for a difficult conversation with my manager?"),
        };

        var response = await GetCoachResponseAsync(messages);

        var context = "The user wants to discuss a promotion they feel they deserve.";

        await scenario.EvaluateAsync(
            messages,
            response,
            additionalContext: [new EvaluationContext("context", context)]);

        var coherence = scenario.GetNumericMetric(CoherenceEvaluator.CoherenceMetricName);
        Assert.IsTrue(coherence.Value >= 3, $"Coherence score {coherence.Value} is below threshold.");
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        // Uses the OTLP-exporting chat client from the Aspire AppHost for judging.
        return new ChatConfiguration(
            chatClientFactory: _ => GetJudgeChatClient(),
            tokenCountingChatClientFactory: _ => GetJudgeChatClient());
    }

    private static IChatClient GetJudgeChatClient()
    {
        // In a real setup, resolve from DI or build from configuration.
        // This placeholder shows the wiring point.
        throw new NotImplementedException(
            "Wire the judge IChatClient via Aspire.Hosting.Testing or a configured Azure OpenAI endpoint.");
    }

    private static Task<ChatMessage> GetCoachResponseAsync(IList<ChatMessage> messages)
    {
        // In a real setup, call into the Coach service via the Aspire test host.
        throw new NotImplementedException(
            "Wire the Coach service via Aspire.Hosting.Testing DistributedApplicationTestingBuilder.");
    }
}

