using Microsoft.Extensions.AI;
using OpenTelemetry;
using OpenTelemetry.Metrics;
using OpenTelemetry.Trace;

namespace MyApp.Evaluations;

/// <summary>
/// Configures OpenTelemetry for AI telemetry capture during evaluations.
/// Exports traces and metrics for gen_ai.* and Microsoft.Extensions.AI.* activity sources.
/// </summary>
public static class TelemetryConfiguration
{
    public static IServiceCollection AddEvaluationTelemetry(
        this IServiceCollection services,
        string otlpEndpoint = "http://localhost:4317")
    {
        services.AddOpenTelemetry()
            .WithTracing(builder => builder
                .AddSource("Microsoft.Extensions.AI.*")
                .AddSource("gen_ai.*")
                .AddOtlpExporter(o => o.Endpoint = new Uri(otlpEndpoint)))
            .WithMetrics(builder => builder
                .AddMeter("Microsoft.Extensions.AI.*")
                .AddMeter("gen_ai.*")
                .AddOtlpExporter(o => o.Endpoint = new Uri(otlpEndpoint)));

        return services;
    }
}

